// Validates and normalizes the request sent by the Angular app before any quota is consumed.
const UNITS = ['gram', 'kg', 'ml', 'liter', 'piece'];
const COOKING_TIMES = ['quick', 'medium', 'complex'];
const CUISINES = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const DIETS = ['vegetarian', 'vegan', 'keto', 'none'];
const NAME_PATTERN = /^[\p{L}\p{N} '()\-]{1,60}$/u;
const MAX_INGREDIENTS = 30;

let body = $json.body ?? null;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (error) {
    body = null;
  }
}
const payload = body && typeof body === 'object' && body.data && typeof body.data === 'object' ? body.data : body;
const errors = [];

if (!payload || typeof payload !== 'object') errors.push('The request body must be a JSON object.');

const rawIngredients = Array.isArray(payload?.ingredients) ? payload.ingredients : [];
if (rawIngredients.length < 1) errors.push('At least 1 ingredient is required.');
if (rawIngredients.length > MAX_INGREDIENTS) errors.push(`No more than ${MAX_INGREDIENTS} ingredients are allowed.`);

const merged = new Map();
rawIngredients.slice(0, MAX_INGREDIENTS).forEach((item, index) => {
  const name = String(item?.name ?? '').trim().replace(/\s+/g, ' ');
  const quantity = Number(item?.quantity);
  const unit = String(item?.unit ?? '').trim().toLowerCase();
  const label = `Ingredient ${index + 1}`;
  let valid = true;

  if (!NAME_PATTERN.test(name)) {
    errors.push(`${label}: the name must be 1-60 letters, numbers, spaces, hyphens, apostrophes or parentheses.`);
    valid = false;
  }
  if (!Number.isFinite(quantity) || quantity <= 0 || quantity > 100000) {
    errors.push(`${label}: the quantity must be a number greater than 0.`);
    valid = false;
  }
  if (!UNITS.includes(unit)) {
    errors.push(`${label}: the unit must be one of ${UNITS.join(', ')}.`);
    valid = false;
  }
  if (!valid) return;

  // Duplicate entries with the same unit are merged instead of rejected.
  const key = `${name.toLowerCase()}|${unit}`;
  const existing = merged.get(key);
  merged.set(key, existing ? { ...existing, quantity: existing.quantity + quantity } : { name, quantity, unit });
});

const preferences = payload?.preferences ?? {};
const portions = Number(preferences.portions);
const cooks = Number(preferences.cooks);
const cookingTime = String(preferences.cookingTime ?? '').toLowerCase();
const cuisine = String(preferences.cuisine ?? '').toLowerCase();
const diets = Array.isArray(preferences.diets)
  ? [...new Set(preferences.diets.map((diet) => String(diet).toLowerCase()))]
  : [];

if (!Number.isInteger(portions) || portions < 1 || portions > 12) errors.push('Portions must be a whole number between 1 and 12.');
if (!Number.isInteger(cooks) || cooks < 1 || cooks > 3) errors.push('Cooks must be a whole number between 1 and 3.');
if (!COOKING_TIMES.includes(cookingTime)) errors.push(`The cooking time must be one of ${COOKING_TIMES.join(', ')}.`);
if (!CUISINES.includes(cuisine)) errors.push(`The cuisine must be one of ${CUISINES.join(', ')}.`);
if (!diets.length || diets.some((diet) => !DIETS.includes(diet))) errors.push(`Diets must contain one or more of ${DIETS.join(', ')}.`);
if (diets.includes('none') && diets.length > 1) errors.push('"none" cannot be combined with other diets.');

return [{
  json: {
    ...$json,
    requestValid: errors.length === 0,
    validationErrors: errors,
    validationMessage: errors.length ? `Invalid request: ${errors[0]}` : null,
    request: {
      ingredients: [...merged.values()],
      preferences: { portions, cooks, cookingTime, cuisine, diets },
    },
  },
}];

// Enforces the per-IP daily quota, the global daily quota and a short throttle between requests of one IP.
const PER_IP_LIMIT = 3;
const GLOBAL_LIMIT = 12;
const THROTTLE_MS = 15000;
// Your own Firebase Realtime Database URL (same value as firebaseDatabaseUrl in the Angular environment).
const dbUrl = 'https://code-a-cuisine-7b803-default-rtdb.europe-west1.firebasedatabase.app';
// Code nodes on n8n Cloud have no global fetch, so Firebase is reached through n8n's HTTP helper.
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

const IPV4 = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
const isIpv6 = (value) => value.length <= 45 && value.includes(':') && /^[0-9a-f:.]+$/i.test(value) && value.split('::').length <= 2;
const detectIpVersion = (value) => (IPV4.test(value) ? 'ipv4' : isIpv6(value) ? 'ipv6' : 'unknown');

// The webhook runs behind a proxy, so the caller IP comes from the forwarding headers.
const headers = $json.headers ?? {};
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const candidates = [
  headers['cf-connecting-ip'],
  headers['x-real-ip'],
  String(headers['x-forwarded-for'] || '').split(',')[0],
  body.clientIp,
].map((value) => String(value ?? '').trim()).filter(Boolean);
const ip = candidates.find((value) => detectIpVersion(value) !== 'unknown') ?? 'unknown';
const ipVersion = detectIpVersion(ip);
const ipSlug = ip.replace(/[^a-zA-Z0-9]/g, '-');

const now = Date.now();
const today = new Date(now).toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const perIpPath = `${dbUrl}/quota/${today}/ips/${ipSlug}.json`;
const globalPath = `${dbUrl}/quota/${today}/global.json`;

// Static data keeps a local copy so the quota still works if Firebase is unreachable.
const staticData = $getWorkflowStaticData('global');
if (!staticData.quotaDaily || typeof staticData.quotaDaily !== 'object') staticData.quotaDaily = {};
for (const day of Object.keys(staticData.quotaDaily)) {
  if (day !== today) delete staticData.quotaDaily[day];
}
const localDay = staticData.quotaDaily[today] ?? (staticData.quotaDaily[today] = { global: 0, ips: {} });

const readJson = async (url) => {
  try {
    return { ok: true, data: await httpRequest({ method: 'GET', url, json: true }) };
  } catch (error) {
    return { ok: false, data: null, error: error.message };
  }
};
const writeJson = (url, value) => httpRequest({
  method: 'PUT',
  url,
  body: JSON.stringify(value),
  headers: { 'Content-Type': 'application/json' },
});

const [ipResult, globalResult] = await Promise.all([readJson(perIpPath), readJson(globalPath)]);
const remoteIp = ipResult.ok && ipResult.data && typeof ipResult.data === 'object' ? ipResult.data : {};
const localIp = localDay.ips[ipSlug] ?? {};
const perIpUsed = Math.max(Number(remoteIp.count) || 0, Number(localIp.count) || 0);
const lastRequestAt = Math.max(Number(remoteIp.lastRequestAt) || 0, Number(localIp.lastRequestAt) || 0);
const globalUsed = Math.max(globalResult.ok ? Number(globalResult.data) || 0 : 0, Number(localDay.global) || 0);

const buildQuota = (ipUsed, globalCount) => ({
  date: today,
  ipAddress: ip,
  ipVersion,
  perIpLimit: PER_IP_LIMIT,
  perIpUsed: ipUsed,
  perIpRemaining: Math.max(0, PER_IP_LIMIT - ipUsed),
  globalLimit: GLOBAL_LIMIT,
  globalUsed: globalCount,
  globalRemaining: Math.max(0, GLOBAL_LIMIT - globalCount),
});

let quotaOk = true;
let quotaErrorCode = null;
let quotaExceededMessage = null;
let quotaWarning = null;
const waitSeconds = Math.ceil((THROTTLE_MS - (now - lastRequestAt)) / 1000);

if (ipVersion === 'unknown') {
  quotaOk = false;
  quotaErrorCode = 'IP_NOT_DETECTED';
  quotaExceededMessage = 'Your IP address could not be detected, so no quota can be assigned. Please try again later.';
} else if (perIpUsed >= PER_IP_LIMIT) {
  quotaOk = false;
  quotaErrorCode = 'QUOTA_EXCEEDED';
  quotaExceededMessage = `Daily limit reached: ${PER_IP_LIMIT} recipe generations per IP address per day. Please come back tomorrow.`;
} else if (globalUsed >= GLOBAL_LIMIT) {
  quotaOk = false;
  quotaErrorCode = 'GLOBAL_QUOTA_EXCEEDED';
  quotaExceededMessage = `The app has reached its daily limit of ${GLOBAL_LIMIT} recipe generations. Please come back tomorrow.`;
} else if (now - lastRequestAt < THROTTLE_MS) {
  quotaOk = false;
  quotaErrorCode = 'THROTTLED';
  quotaExceededMessage = `Too many requests. Please wait ${waitSeconds} seconds before generating again.`;
}

let quota = buildQuota(perIpUsed, globalUsed);

if (quotaOk) {
  const nextIp = { count: perIpUsed + 1, lastRequestAt: now, ipVersion };
  const nextGlobal = globalUsed + 1;
  localDay.ips[ipSlug] = nextIp;
  localDay.global = nextGlobal;

  const writeErrors = [];
  try {
    await writeJson(perIpPath, nextIp);
  } catch (error) {
    writeErrors.push(`per-ip write: ${error.message}`);
  }
  try {
    await writeJson(globalPath, nextGlobal);
  } catch (error) {
    writeErrors.push(`global write: ${error.message}`);
  }
  if (writeErrors.length) {
    quotaWarning = `Firebase sync failed, local fallback is active: ${writeErrors.join(' | ')}`;
    console.log(quotaWarning);
  }
  quota = buildQuota(nextIp.count, nextGlobal);
}

return [{
  json: {
    ...$json,
    ipAddress: ip,
    ipVersion,
    ipSlug,
    quotaDate: today,
    quotaOk,
    quotaErrorCode,
    quotaExceededMessage,
    quotaWarning,
    quota,
  },
}];

// Builds the recipe prompt from the validated request. On a retry the rejection reasons are appended.
const { request, attempt = 1, retryFeedback = null } = $json;
const { ingredients, preferences } = request;

const COOKING_TIMES = {
  quick: 'quick, at most 20 minutes in total',
  medium: 'medium, between 20 and 45 minutes in total',
  complex: 'elaborate, more than 45 minutes in total',
};
const CUISINES = {
  german: 'German cuisine',
  italian: 'Italian cuisine',
  indian: 'Indian cuisine',
  japanese: 'Japanese cuisine',
  gourmet: 'Gourmet / fine dining',
  fusion: 'Fusion, an international mix of styles',
};
const DIET_RULES = {
  vegetarian: 'Vegetarian: no meat, poultry, fish, seafood or gelatine.',
  vegan: 'Vegan: no animal products at all (no meat, fish, dairy, eggs, honey or gelatine).',
  keto: 'Keto: at most 20 g net carbohydrates per portion; no sugar, flour, rice, pasta, potatoes or bread.',
  none: 'No dietary restrictions.',
};
const UNIT_LABELS = { gram: 'g', kg: 'kg', ml: 'ml', liter: 'l', piece: 'piece(s)' };

const minUsed = Math.ceil(ingredients.length * 0.7);
const ingredientList = ingredients
  .map((item) => `- ${item.name}: ${item.quantity} ${UNIT_LABELS[item.unit] ?? item.unit} available`)
  .join('\n');
const dietRules = preferences.diets.map((diet) => `  - ${DIET_RULES[diet]}`).join('\n');
const cooksRule = preferences.cooks > 1
  ? `Split the work between the ${preferences.cooks} cooks so that every cook has their own tasks. Steps that different cooks do at the same time get "parallel": true.`
  : 'There is only one cook: set "cook" to 1 and "parallel" to false for every step.';

let prompt = `Create exactly 3 recipes from the ingredients a home cook already has.

Available ingredients:
${ingredientList}

Preferences:
- Portions: ${preferences.portions}
- People cooking together: ${preferences.cooks}
- Time frame: ${COOKING_TIMES[preferences.cookingTime]}
- Cuisine: ${CUISINES[preferences.cuisine]}
- Diet:
${dietRules}

Rules:
1. The 3 recipes must clearly differ in cooking method (for example pan, oven, raw, soup) or flavour profile.
2. Each recipe uses at least ${minUsed} of the ${ingredients.length} available ingredients. Copy their names exactly as written above. Leave out an available ingredient only if it breaks the diet rules.
3. Each recipe may add at most 3 extra basic ingredients (for example salt, pepper, oil, water or a common spice). List them in "extraIngredients" and also in "ingredients".
4. Scale all quantities in "ingredients" for exactly ${preferences.portions} portion(s) and never use more than the available amount. Format: "<quantity> <unit> <name>", for example "200 g pasta".
5. "estimatedMinutes" must fit the time frame.
6. Use spices, techniques and dishes that are typical for the cuisine.
7. Steps are chronological, easy to follow for beginners and 4 to 12 per recipe. Every step has a short "title" (2-6 words), a clear "instruction", "cook" (1 to ${preferences.cooks}) and "durationMinutes".
8. ${cooksRule}
9. Use waiting times (boiling, baking, resting) for other preparations and say so in the instruction.
10. "nutrition" contains realistic estimates in kcal and grams: "perPortion" for one portion and "total" for the whole recipe (${preferences.portions} portion(s)).`;

// Without an output parser the model needs the exact JSON shape in the prompt.
prompt += `

Answer with one JSON object only, no markdown, exactly in this shape:
{
  "recipes": [
    {
      "title": "string",
      "description": "one or two sentences",
      "estimatedMinutes": 25,
      "ingredients": ["200 g pasta", "150 g tomato", "1 tbsp olive oil"],
      "extraIngredients": ["1 tbsp olive oil"],
      "steps": [
        { "title": "Boil the pasta", "instruction": "string", "cook": 1, "parallel": false, "durationMinutes": 10 }
      ],
      "nutrition": {
        "perPortion": { "calories": 520, "protein": 17, "carbs": 80, "fat": 12 },
        "total": { "calories": 1040, "protein": 34, "carbs": 160, "fat": 24 }
      }
    }
  ]
}`;

if (retryFeedback) {
  prompt += `\n\nYour previous answer was rejected for these reasons: ${retryFeedback}\nCreate new recipes that fix every point.`;
}

return [{ json: { ...$json, prompt, attempt, retryFeedback } }];

// Checks the AI answer against the recipe rules. Rule violations trigger one retry, unusable answers become an error.
const MAX_ATTEMPTS = 2;
const promptData = $('Prepare Prompt').last().json;
const quotaData = $('Check IP Quota').first().json;
const { ingredients: requested, preferences } = promptData.request;
const attempt = Number(promptData.attempt) || 1;

let answer = $json.output ?? $json.text ?? $json;
if (typeof answer === 'string') {
  const cleaned = answer.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    answer = JSON.parse(cleaned);
  } catch (error) {
    answer = null;
  }
}

const normalize = (value) => String(value ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const toAmount = (value) => {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? Math.round(number) : null;
};
const toMacros = (value) => ({
  calories: toAmount(value?.calories),
  protein: toAmount(value?.protein),
  carbs: toAmount(value?.carbs),
  fat: toAmount(value?.fat),
});
const isComplete = (macros) => Object.values(macros).every((amount) => amount !== null);
const toList = (value) => (Array.isArray(value) ? value : []).map((item) => String(item).trim()).filter(Boolean);

const hardIssues = [];
const softIssues = [];
const rawRecipes = Array.isArray(answer?.recipes) ? answer.recipes : [];
if (rawRecipes.length !== 3) hardIssues.push(`Expected exactly 3 recipes but got ${rawRecipes.length}.`);

const recipes = rawRecipes.slice(0, 3).map((raw, index) => {
  const label = `Recipe ${index + 1}`;
  const title = String(raw?.title ?? '').trim();
  const description = String(raw?.description ?? '').trim();
  const estimatedMinutes = toAmount(raw?.estimatedMinutes);
  const ingredients = toList(raw?.ingredients);
  const extraIngredients = toList(raw?.extraIngredients);

  const stepDetails = (Array.isArray(raw?.steps) ? raw.steps : []).map((step) => {
    if (typeof step === 'string') {
      const [head, ...rest] = step.split(':');
      return {
        title: rest.length ? head.trim() : '',
        instruction: (rest.length ? rest.join(':') : step).trim(),
        cook: 1,
        parallel: false,
        durationMinutes: 0,
      };
    }
    const cook = Math.min(preferences.cooks, Math.max(1, Math.round(Number(step?.cook)) || 1));
    return {
      title: String(step?.title ?? '').trim(),
      instruction: String(step?.instruction ?? '').trim(),
      cook,
      parallel: preferences.cooks > 1 && step?.parallel === true,
      durationMinutes: toAmount(step?.durationMinutes) ?? 0,
    };
  }).filter((step) => step.instruction);

  const nutrition = { perPortion: toMacros(raw?.nutrition?.perPortion), total: toMacros(raw?.nutrition?.total) };
  if (!isComplete(nutrition.total) && isComplete(nutrition.perPortion)) {
    nutrition.total = Object.fromEntries(
      Object.entries(nutrition.perPortion).map(([key, amount]) => [key, amount * preferences.portions]),
    );
  }

  if (!title || !description) hardIssues.push(`${label}: title and description are required.`);
  if (!estimatedMinutes) hardIssues.push(`${label}: estimatedMinutes must be a positive number.`);
  if (!ingredients.length) hardIssues.push(`${label}: the ingredient list is empty.`);
  if (stepDetails.length < 4 || stepDetails.length > 12) hardIssues.push(`${label}: needs 4 to 12 steps but has ${stepDetails.length}.`);
  if (!isComplete(nutrition.perPortion) || !isComplete(nutrition.total)) {
    hardIssues.push(`${label}: nutrition per portion and for the whole recipe is incomplete.`);
  }

  const ingredientText = ingredients.map(normalize);
  const used = requested.filter((item) => ingredientText.some((text) => text.includes(normalize(item.name)))).length;
  const minUsed = Math.ceil(requested.length * 0.7);
  if (used < minUsed) softIssues.push(`${label} uses ${used} of the available ingredients, at least ${minUsed} are required.`);
  if (extraIngredients.length > 3) softIssues.push(`${label} adds ${extraIngredients.length} extra ingredients, at most 3 are allowed.`);
  if (preferences.cooks > 1) {
    const idleCooks = Array.from({ length: preferences.cooks }, (_, i) => i + 1)
      .filter((cook) => !stepDetails.some((step) => step.cook === cook));
    if (idleCooks.length) softIssues.push(`${label}: cook ${idleCooks.join(' and ')} has no tasks.`);
  }

  return {
    title,
    description,
    estimatedMinutes,
    ingredients,
    extraIngredients,
    steps: stepDetails.map((step) => (step.title ? `${step.title}: ${step.instruction}` : step.instruction)),
    stepDetails,
    nutrition,
    ingredientCoverage: requested.length ? Math.round((used / requested.length) * 100) : 100,
  };
});

const titles = recipes.map((recipe) => normalize(recipe.title));
if (new Set(titles).size !== titles.length) softIssues.push('The 3 recipes need different titles and must differ in method or flavour.');

if ((hardIssues.length || softIssues.length) && attempt < MAX_ATTEMPTS) {
  return [{
    json: { ...promptData, attempt: attempt + 1, retry: true, retryFeedback: [...hardIssues, ...softIssues].join(' ') },
  }];
}

if (hardIssues.length) {
  return [{
    json: {
      ...quotaData,
      retry: false,
      recipeError: true,
      recipeErrorMessage: 'The AI could not create valid recipes. Please try again.',
      recipeIssues: hardIssues,
      attempts: attempt,
    },
  }];
}

return [{
  json: {
    ...quotaData,
    ingredients: requested,
    preferences,
    retry: false,
    recipeError: false,
    recipeErrorMessage: null,
    recipeWarnings: softIssues,
    attempts: attempt,
    recipeResult: { recipes },
  },
}];

// Logs a failed recipe generation to the execution log and to Firebase, then passes the item on to the error response.
const dbUrl = 'https://code-a-cuisine-7b803-default-rtdb.europe-west1.firebasedatabase.app';
const entry = {
  at: new Date().toISOString(),
  workflow: $workflow.name,
  executionId: $execution.id,
  message: $json.recipeErrorMessage ?? $json.error?.message ?? 'Recipe generation failed',
  issues: $json.recipeIssues ?? [],
  ipVersion: $('Check IP Quota').first().json.ipVersion ?? 'unknown',
};

console.log(`Recipe generation failed: ${entry.message} ${entry.issues.join(' ')}`);
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${dbUrl}/logs/recipeErrors.json`,
    body: JSON.stringify(entry),
    headers: { 'Content-Type': 'application/json' },
  });
} catch (error) {
  console.log(`Writing the error log failed: ${error.message}`);
}

return [{ json: { ...$json, recipeErrorMessage: entry.message } }];
